<script setup lang="ts">
import zh from '../../../i18n/locales/zh-CN.json'
import en from '../../../i18n/locales/en-US.json'
import ja from '../../../i18n/locales/ja-JP.json'
const props=defineProps<{taskId:string}>()
const {t:uiT,locale:appLocale}=useI18n({useScope:'global'})
const preference=useCookie<string|null>('wms_print_language',{maxAge:31536000,sameSite:'lax'})
const initial=preference.value||appLocale.value
const {t,locale}=useI18n({useScope:'local',inheritLocale:false,locale:initial==='zh'||initial==='ja'?initial:'en',messages:{zh,en,ja}})
watch(locale,value=>preference.value=value)
const blind=ref(true),record=ref<any>(null),loading=ref(true),error=ref(''),staff=useStaffStore(),{bizErrorMessage}=useBizError()
const company=computed(()=>staff.staffInfo?.company as any),number=computed(()=>'CC-'+props.taskId)
const rows=computed(()=>(record.value?.task_details||[]).slice().sort((a:any,b:any)=>String(a.location?.code||'').localeCompare(String(b.location?.code||''),undefined,{numeric:true})||a.id-b.id))
const locationCount=computed(()=>new Set(rows.value.map((r:any)=>r.location_id)).size)
const goodsCount=computed(()=>new Set(rows.value.map((r:any)=>r.goods_id)).size)
const print=async()=>{await document.fonts.ready;window.print()}
let generation=0
watch(()=>props.taskId,async()=>{const seq=++generation;record.value=null;loading.value=true;error.value='';const result=await httpRequest<any>('/api/warehouse/cyclecount/'+props.taskId,{onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(seq===generation){record.value=result;loading.value=false}},{immediate:true})
onBeforeUnmount(()=>generation++)
useHead({title:()=>number.value+' · '+t('count-print.title')})
</script>
<template>
 <div class="count-print w-scope">
  <div class="toolbar"><NuxtLink :to="'/cyclecount/detail/'+taskId">{{number}}</NuxtLink><label>{{uiT('print-design.language')}}<select v-model="locale"><option value="zh">中文</option><option value="en">English</option><option value="ja">日本語</option></select></label><label><input v-model="blind" type="checkbox"/>{{t('count-print.blind')}}</label><WButton icon="printer" :disabled="loading||!record" @click="print">{{uiT('button.print-to-pdf')}}</WButton></div>
  <WAlert v-if="error" tone="block" :title="error"/><WEmptyState v-if="loading" :title="uiT('common.status.loading')"/>
  <div class="paper-scroll"><article v-if="record" class="paper" :lang="locale==='ja'?'ja':locale==='zh'?'zh-CN':'en'">
   <header><div class="company"><strong>{{company?.name}}</strong><span>{{company?.address}}</span><span>{{company?.phone}}<template v-if="company?.email"> · {{company.email}}</template></span></div><div class="title"><h1>STOCK COUNT SHEET</h1><span>{{t('count-print.title')}}</span><div class="barcode-row"><b class="stamp">{{blind?'BLIND COUNT':'STANDARD COUNT'}}</b><div><Barcode :value="number" :options="{displayValue:false,margin:0,height:32}"/><b class="number">{{number}}</b></div></div></div></header>
   <div class="references"><div><small>COUNT NO. · {{t('count-print.number')}}</small><b>{{number}}</b></div><div><small>WAREHOUSE · {{t('nav.warehouse')}}</small><b>{{record.warehouse?.name}}</b></div><div><small>PLANNED · {{t('count-print.planned')}}</small><b>{{record.scheduled_date?$dayjs(record.scheduled_date,'YYYY-MM-DD',record):'—'}}</b></div><div><small>MODE · {{t('count-print.mode')}}</small><b>{{t(blind?'count-print.blind':'count-print.standard')}}</b></div></div>
   <div class="summary"><div><small>LOCATIONS · {{t('nav.location')}}</small><b>{{locationCount}}</b></div><div><small>GOODS · {{t('nav.goods')}}</small><b>{{goodsCount}}</b></div><div><small>LINES · {{t('count-print.lines')}}</small><b>{{rows.length}}</b></div><div><small>{{t('common.fields.name')}}</small><b>{{record.task_name||'—'}}</b></div></div>
   <h2>COUNT LINES · BY LOCATION <span>{{t('count-print.by-location')}}</span></h2>
   <table class="count-lines"><colgroup><col style="width:30px"/><col style="width:74px"/><col/><col style="width:66px"/><col style="width:78px"/><col v-if="!blind" style="width:50px"/><col style="width:70px"/><col style="width:90px"/></colgroup><thead><tr><th>#</th><th>LOCATION<span>{{t('nav.location')}}</span></th><th>GOODS<span>{{t('nav.goods')}}</span></th><th>LOT<span>{{t('count-print.lot')}}</span></th><th>EXPIRY<span>{{t('count-print.expiry')}}</span></th><th v-if="!blind" class="qty">SYSTEM<span>{{t('common.quantities.system')}}</span></th><th>COUNT<span>{{t('common.quantities.actual')}}</span></th><th>{{blind?'NOTES':'DIFFERENCE'}}<span>{{t(blind?'common.fields.remark':'operations.ui.variance')}}</span></th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="row.id"><td class="seq">{{Number(index)+1}}</td><td class="location">{{row.location?.code||'—'}}</td><td><b>{{row.goods?.name}}</b><span class="code">{{row.goods?.code}}</span></td><td>{{row.lot?.lot_number||'—'}}</td><td>{{row.lot?.expiry_date||'—'}}</td><td v-if="!blind" class="qty">{{row.system_quantity??'—'}}</td><td><i class="write-box"/></td><td><i :class="blind?'write-line':'write-box'"/></td></tr></tbody></table>
   <h2>EXCEPTIONS <span>{{t('count-print.exceptions')}}</span></h2><table class="exceptions"><thead><tr><th>{{t('nav.location')}}</th><th>{{t('nav.goods')}}</th><th>{{t('count-print.lot')}}</th><th>{{t('common.quantities.actual')}}</th><th>{{t('common.fields.remark')}}</th></tr></thead><tbody><tr v-for="n in 4" :key="n"><td/><td/><td/><td/><td/></tr></tbody></table>
   <div class="closing"><div class="signatures"><section v-for="key in ['counted','reviewed']" :key="key"><h3>{{t('count-print.'+key)}}</h3><div><span v-for="field in ['common.fields.name','print-design.signature','print-design.date']" :key="field">{{t(field)}}<i/></span></div></section></div><footer><span>{{company?.name}}</span><span>{{number}} · {{t(blind?'count-print.blind':'count-print.standard')}}</span></footer></div>
  </article></div>
 </div>
</template>
